{
 "research_concepts": [
  "Play type labeling",
  "AVOID labels",
  "Points Per Possession (PPP)",
  "Defensive outcomes after offensive actions",
  "Sequential effects in basketball",
  "Lag analysis of play outcomes",
  "Data quality and artifacts in basketball analytics"
 ],
 "methodological_questions": [
  "Measurement of opponent next-possession PPP",
  "Attribution of defensive outcomes to prior offensive play types",
  "Definition and analysis of 'own-sequence lags' in basketball",
  "Identification of confounding factors in sequential play analysis",
  "Established methods for assigning 'AVOID' or similar labels to basketball plays",
  "Reliability and accuracy of inferred play-type labels"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF07",
   "status_as_recorded": "supported",
   "finding": "[APPA-049] A2 aftershock 8/8 PTs replicate all-games and playoffs (CUT +0.119 n=21,398 / PO +0.131 n=1,145 through TRANSITION +0.135 n=26,262 / +0.126 n=1,529). Top pair premiums: PUTBACK->TRANSITION +0.084 n=565; CUT->P [cut; read_family for the full text]. [APPS-037] All-games aftershock after success: CUT +0.119 (n=21398), DRIVE +0.123 (57621), PNR +0.127 (51194), POST_UP +0.128 (20619), PULL_UP +0.132 (26060), PUTBACK +0.130 (5888), SPOT_UP +0.128 (43857), TRANSITION +0. [cut; read_family for the full text]"
  },
  {
   "id": "FAM:SF-APPS-075",
   "status_as_recorded": "not a hypothesis test",
   "finding": "4/8 PTs downstream real: CUT Ext 1.658 (supp +0.0220), TRANSITION 1.509 (+0.0145), SPOT_UP 1.303 (+0.0124), POST_UP 1.127 (+0.0194). DRIVE downstream not real (opp ATT +0.0024). Player downstream mostly BH ns except M. M [cut; read_family for the full text]"
  },
  {
   "id": "FAM:SF-APPM-001",
   "status_as_recorded": "supported",
   "finding": "Raw gap aligned-deviated +5.18 ORtg; strength-controlled gap +3.27 ORtg (+0.0193 vs -0.0134 PPP residual). Model regret median +25.94 ORtg (non-negative by construction)."
  },
  {
   "id": "FAM:SF-APPA-050",
   "status_as_recorded": "not a hypothesis test",
   "finding": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]"
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Attempt to label on-ball defensive schemes (DROP/ICE/SWITCH) using NBA matchup/PBP fields.",
   "why": "Confident label rates were very low (14.9% and 3.3%); 'switches_on' field was unpopulated. Limited by LABEL_ERROR and SAMPLE_SIZE_POWER."
  },
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Using possession-level play types from PBP to infer predictive structure.",
   "why": "Assisted flag existed only on makes, producing an artifact where SPOT_UP PPP was inflated (2.83 PPP, 100% makes) and TRANSITION PPP was deflated. Classified as C_artifact."
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Audit of inferred play-type label accuracy and distribution.",
   "why": "Overall FAIL: 'OTHER' category too high (20.2% vs <10% target), 40.8% low confidence labels, DRIVE foul-draw rate too low (1.7% vs 14-22% benchmark), most PTs PPP above benchmark. Attributed to C_artifact, LABEL_ERROR, LEAKAGE_LOOKAHEAD, SAMPLE_SIZE_POWER."
  },
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Play-type labeling audit to distinguish real efficiency from labeling/foul artifacts.",
   "why": "Found 'OTHER' PPP inflated by 36% foul endings and DRIVE PPP 12pp below foul benchmark. Only 0.7% of possessions mapped to a real play type via 'initiation_type'. Classified as C_artifact."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Studying defensive scheme changes within and across games using inferred labels.",
   "why": "Inferred labels could not separate real defensive adjustments from offensive execution differences, and near-uniform transition matrices were consistent with label noise. Limited by LABEL_ERROR."
  },
  {
   "id": "FAM:SF-APPA-030",
   "what_failed": "Verification of backfilled play-type labels.",
   "why": "PNR and PULL_UP distributions did not match expected, and team identity checks failed. Attributed to C_artifact, LABEL_ERROR."
  },
  {
   "id": "FAM:SF-APPA-050",
   "what_failed": "Identifying specific opponent play types that suppress a star's next-possession PPP.",
   "why": "No multiplicity correction was applied, and sample sizes for specific 'n_after' cells were small (32-95) compared to baseline possessions, leading to an unclear mechanism (E_unclear) and RISK:DRIFT_NONSTATIONARITY."
  },
  {
   "id": "FAM:SF-APPS-075",
   "what_failed": "Identifying play types and players with a real downstream (opponent next-PPP) component.",
   "why": "Downstream effects were small (~0.01-0.02 PPP) relative to direct PPP gaps, and player list was mostly non-FINDING after BH correction. Mechanism unclear (E_unclear)."
  }
 ],
 "evidence_establishes": [
  "Sequential effects on Points Per Possession (PPP) exist, where a preceding play type can influence the PPP of a subsequent possession (FAM:SF07, FAM:SF-APPS-075).",
  "There is evidence of a 'defensive aftershock' where, after an opponent runs play type X, the next offensive play type Y scores above Y's unconditional baseline (FAM:SF07).",
  "Play-type efficiency is measurable, and aligning a team's play-type mix to a recommended mix can lead to improved offensive efficiency (FAM:SF-APPM-001).",
  "There are persistent and significant data quality issues with inferred play-type labels, often leading to artifacts, unreliable results, or untestable hypotheses (FAM:SF-PAP-096, FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030, FAM:SF-APPS-058, FAM:SF-APPA-005). These issues include low confidence, incorrect distributions, foul leakage, and inability to distinguish real adjustments from noise.",
  "Directly labeling defensive schemes from PBP data is challenging and often results in very low confident label rates and small sample sizes (FAM:SF-APPS-058, FAM:SF-APPA-005)."
 ],
 "evidence_does_not_establish": [
  "Whether the magnitude of 'opponent next-possession PPP after you run play X' is 'large enough to drive AVOID labels'. The concept of 'AVOID labels' as a decision-making construct or a specific threshold is not defined or tested in the historical evidence.",
  "A clear causal mechanism for the observed sequential PPP effects, or how these effects translate into explicit coaching or player decisions to 'AVOID' certain plays (FAM:SF-APPS-075, FAM:SF-APPA-005).",
  "The reliability or existence of 'own-sequence lags' in driving 'AVOID labels' specific to the team's own offensive sequence, beyond the general concept of sequential effects.",
  "Whether the observed sequential effects are robust enough to overcome the pervasive issues with play-type label quality and sample size limitations, especially for specific, fine-grained interactions."
 ],
 "own_inferences": [
  "The research question implies a need to define and operationalize 'AVOID labels', which is a higher-level decision or recommendation, not a direct observation in the available data. This will likely require a derived label with its own validation challenges.",
  "The 'large enough' criterion for PPP to drive AVOID labels will need to be explicitly defined and justified, potentially introducing a subjective threshold.",
  "Measuring 'own-sequence lags' suggests looking at previous offensive possessions by the same team, which could be confounded by game state, player availability, and opponent adjustments. The causal attribution will be difficult."
 ],
 "uncertainties": [
  "The precise definition and source of 'AVOID labels' are unclear. Are these external expert labels, or are they to be derived from data? If derived, how?",
  "The specific methodology for identifying and quantifying 'own-sequence lags' is not detailed, and how they would 'similarly matter' needs to be operationalized.",
  "The extent to which the identified play-type labeling issues (e.g., high 'OTHER' category, foul leakage, low confidence) impact the specific play types relevant to this research question."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly highlights the pervasive and critical issues with play-type label quality (LABEL_ERROR, C_artifact) across multiple studies, which were not initially fully appreciated for their severity. This evidence transforms the decision from a potential 'proceed_with_changes' focused on statistical methods to a 'do_not_proceed' due to fundamental data quality blocking constraints. The repeated failures to produce reliable play-type labels or to attribute effects due to label noise make the core premise of analyzing play-type specific sequential effects highly unreliable without first resolving the underlying labeling problems. While sequential effects on PPP are shown to exist, their reliability and interpretability given current label quality are severely compromised, making the 'AVOID label' derivation untestable."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The project's historical record shows consistent and severe issues with the accuracy, reliability, and confidence of inferred play-type labels (e.g., FAM:SF-PAP-096, FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030). These issues lead to artifacts, high 'OTHER' categories, incorrect foul rates, and an inability to distinguish real effects from label noise. Without highly reliable play-type labels, any analysis of sequential PPP effects tied to specific play types will be confounded or produce spurious results."
   },
   {
    "code": "OUTCOME_DERIVED_LABEL",
    "text": "The concept of 'AVOID labels' is a derived decision or recommendation, not a raw observable in the data. Its definition, operationalization, and validation would be a significant research task in itself, and without clear, reliable inputs (i.e., play-type labels and accurately attributed PPP), its derivation would be highly problematic."
   },
   {
    "code": "CONFOUNDING",
    "text": "Attributing opponent next-possession PPP changes, or 'own-sequence lags', solely to a preceding play type is highly susceptible to confounding by various factors such as game state, player personnel, defensive adjustments, coaching decisions, and inherent noise in basketball possessions. FAM:SF-APPA-005 highlights the difficulty in separating real defensive adjustments from offensive execution differences even with inferred labels."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "While aggregate play-type data is large, analyzing specific sequential interactions (e.g., 'play X' followed by 'play Y' and its impact on 'AVOID labels' for individual teams or players) will likely lead to small sample sizes, as seen in FAM:SF-APPA-050 and FAM:SF-APPS-058, reducing statistical power and increasing the risk of spurious findings."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF07",
   "FAM:SF-APPS-075",
   "FAM:SF-APPM-001"
  ],
  "summary": "Historical work establishes that sequential effects on PPP exist (FAM:SF07, FAM:SF-APPS-075) and that play-type efficiency is measurable (FAM:SF-APPM-001). However, no prior work directly addresses whether these effects are 'large enough to drive AVOID labels' or defines 'AVOID labels'. Critically, a large body of prior work (FAM:SF-PAP-096, FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030, FAM:SF-APPS-058, FAM:SF-APPA-005) consistently highlights severe, fundamental data quality issues with play-type labels themselves, which undermine the reliability of any analysis built upon them."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The primary risk is the unreliability of the underlying play-type labels, which have repeatedly been shown to have systematic issues, leading to artifacts, misclassification, and an inability to accurately represent basketball actions. This will directly impact the validity of measuring PPP for specific play types and attributing sequential effects."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "The 'AVOID labels' concept is not an observable fact but a derived judgment. Defining what constitutes 'large enough' PPP to trigger an 'AVOID' label and how this label would be constructed and validated from the available data presents a significant methodological challenge."
  },
  {
   "code": "CONFOUNDING",
   "text": "The relationship between a preceding play type and subsequent PPP is highly susceptible to confounding by various factors such as game state, opponent adjustments, player skill, and tactical decisions. Isolating the causal effect of 'play X' on subsequent PPP, independent of these confounders, will be extremely difficult."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While overall possession counts are high, interactions between specific play types in sequence, especially when conditioned on team/player, will likely result in small sample sizes for many cells, making it difficult to detect statistically significant and robust effects for 'large enough' PPP changes. Prior studies have faced this issue (FAM:SF-APPA-050, FAM:SF-APPS-058)."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "The definition of PPP has a mechanical floor at 0.0. While this is standard, it might interact with how 'AVOID labels' are conceptualized, especially if low PPP values are considered a primary driver."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "If 'AVOID labels' are to be identified across many play types, players, or sequential combinations, there is a high risk of false positives due to multiple comparisons, which was an issue in FAM:SF-APPA-050."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.05,
  "untestable": 0.6,
  "artifact": 0.25,
  "uncertain": 0.05
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The research question is not testable in its current form due to fundamental data quality issues with play-type labels and the ambiguity of 'AVOID labels'. Therefore, a design for the *posed question* is not feasible.",
  "unit": "If the underlying data quality issues were resolved, the unit of analysis would be a sequential pair of possessions: (offensive play type X by team A, followed by opponent's next possession) or (offensive play type X by team A, followed by team A's next possession).",
  "sample": "If the underlying data quality issues were resolved, the sample would include all team possessions from the NBA 2022-23, 2023-24, 2024-25, and 2025-26 seasons for which reliable play-type labels can be assigned.",
  "power": "Not applicable given the decision not to proceed. If it were to proceed, power calculations would be critical for specific play-type sequences, considering the small sample sizes observed in related studies.",
  "controls": "Not applicable. If proceeded, controls for team strength, opponent strength, game state (score, time), player personnel on court, and shot clock would be essential to mitigate confounding.",
  "falsification": "Not applicable. If proceeded, falsification would involve demonstrating that observed PPP differences for specific sequences are not attributable to labeling artifacts, small sample noise, or confounding factors, and that 'AVOID labels' can be reliably derived and validated against an external benchmark or expert judgment.",
  "multiplicity": "Not applicable. If proceeded, p-value adjustments (e.g., Bonferroni, Benjamini-Hochberg) would be required to account for multiple comparisons across different play types, sequential combinations, and 'AVOID label' thresholds.",
  "decision_rule": "Not applicable.",
  "data_version": "Not applicable. The data available is NBA 2022-23 through 2025-26. However, the critical constraint is the quality of the derived play-type possession records, not the raw NBA stats API data."
 }
}

